state.projects.map((project) => ({
    project,
    tasks: state.tasks.filter((task) => {
      const currentMemberId = state.currentMemberIdsByProject?.[project.id]
        ?? (state.accessMode === 'guest' ? state.currentUserId : null)
      return task.projectId === project.id && task.assigneeId === currentMemberId
    }),
  })).filter

filtered.map((task, index) => ({ task, index })).sort((left, right) => {
      const leftValue = valueFor(left.task)
      const rightValue = valueFor(right.task)
      const comparison = typeof leftValue === 'number'
        ? leftValue - rightValue
        : leftValue.localeCompare(rightValue, 'ko-KR')
      return (sort.direction === 'asc' ? comparison : -comparison) || left.index - right.index
    }).map
